import{_ as e,o as _,c as t,a4 as a}from"./chunks/framework.C3unmAF4.js";const f=JSON.parse('{"title":"县乡消费占社会消费品零售总额比重稳步提升  引导更多品牌连锁企业向县域下沉（权威发布）2026-08-28","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"县乡消费占社会消费品零售总额比重稳步提升  引导更多品牌连锁企业向县域下沉（权威发布）2026-08-28","date":"2026-08-28T00:00:00.000Z","source":"农业农村部市场与信息化司","category":"policies","link":"https://scs.moa.gov.cn/gzdt/202608/t20260828_6487083.htm","summary":"人民日报记者 王 珂\\n《人民日报》（\\n2026年08月19日\\n第 02 版）\\n8月18日，国务院新闻办举行新闻发布会，介绍激发下沉市场活力活跃县域消费有关情况。\\n接续推进农村现代流通体系建设\\n下沉市场覆盖城乡、连接产销、服务民生，承载着最广泛的消费群体，也蕴藏着最具潜力的消费需求，县域是其重要组成部分。...\\n","contentHash":"1cff8947d9dca46af847efb4549302bc","tags":["智慧农业","政策法规"]},"headers":[],"relativePath":"policies/2026-08-28-县乡消费占社会消费品零售总额比重稳步提升-引导更多品牌连锁企业向县域下沉-权威发布.md","filePath":"policies/2026-08-28-县乡消费占社会消费品零售总额比重稳步提升-引导更多品牌连锁企业向县域下沉-权威发布.md"}'),s={name:"policies/2026-08-28-县乡消费占社会消费品零售总额比重稳步提升-引导更多品牌连锁企业向县域下沉-权威发布.md"};function r(o,p,n,c,l,i){return _(),t("div",null,[...p[0]||(p[0]=[a('<h1 id="县乡消费占社会消费品零售总额比重稳步提升-引导更多品牌连锁企业向县域下沉-权威发布-2026-08-28" tabindex="-1">县乡消费占社会消费品零售总额比重稳步提升 引导更多品牌连锁企业向县域下沉（权威发布）2026-08-28 <a class="header-anchor" href="#县乡消费占社会消费品零售总额比重稳步提升-引导更多品牌连锁企业向县域下沉-权威发布-2026-08-28" aria-label="Permalink to &quot;县乡消费占社会消费品零售总额比重稳步提升  引导更多品牌连锁企业向县域下沉（权威发布）2026-08-28&quot;">​</a></h1><blockquote><p>来源: <a href="https://scs.moa.gov.cn/gzdt/202608/t20260828_6487083.htm" target="_blank" rel="noreferrer">农业农村部市场与信息化司</a><br> 日期: 2026-08-28 摘要: 人民日报记者 王 珂 《人民日报》（ 2026年08月19日 第 02 版） 8月18日，国务院新闻办举行新闻发布会，介绍激发下沉市场活力活跃县域消费有关情况。 接续推进农村现代流通体系建设 下沉市场覆盖城乡、连接产销、服务民生，承载着最广泛的消费群体，也蕴藏着最具潜力的消费需求，县域是其重要组成部分。...</p></blockquote><p>8月18日，国务院新闻办举行新闻发布会，介绍激发下沉市场活力活跃县域消费有关情况。</p><p>接续推进农村现代流通体系建设</p><p>下沉市场覆盖城乡、连接产销、服务民生，承载着最广泛的消费群体，也蕴藏着最具潜力的消费需求，县域是其重要组成部分。商务部部长助理袁晓明介绍，我国县域地区约占全国九成国土面积、五成常住人口、四成经济总量，县乡消费占社会消费品零售总额的比重稳步提升，成为扩消费最重要潜力来源。</p><p>近日，商务部会同相关部门印发《关于进一步激发下沉市场活力　活跃县域消费的意见》（以下简称《意见》），推动促消费与惠民生紧密结合，强化新供给与新需求适配联动，以新型城镇化建设培育需求，以高质量设施业态和商品服务丰富供给，以连锁经营等现代流通方式提高效率，以良好营商环境强化保障，更好满足居民品质化、多样化消费需求。</p><p>《意见》主要包括4个方面。一是优化县域商业环境。加快存量商业设施更新，优化商业网点布局，完善商业服务配套，盘活闲置资源资产。提高城乡流通网络效能，畅通城乡双向流通渠道，引导线上线下协同发展。二是丰富县域消费供给。引导连锁企业加速下沉，促进本地品牌守正创新，因地制宜发展新业态。扩大优质优价商品供应，加快完善“一老一小”等服务业态，促进商农文旅体融合发展。三是增强消费保障能力。推动稳岗就业拓展增收途径，强化创业安居释放消费潜力。支持一批企业总部和平台企业在县域布局，提供更多就业岗位，培育扎根县域的新形态就业群体。四是强化要素集成。在财政、金融、土地、营商环境等方面推出一批硬招实招，带动各类资源要素向县域集聚。</p><p>2021年以来，商务部深入推进县域商业体系建设，有力带动农民收入和农村消费双提升。</p><p>流通设施持续提档升级。建设改造县城综合商贸服务中心3159个，乡镇商贸中心1.5万个，村级便民商店16.8万个，全国基本实现县乡村三级商业网点全覆盖。</p><p>物流配送体系日趋健全。累计支持升级改造县乡物流配送网点3600多个，每天有超过1亿件包裹进出农村。</p><p>农产品供应链转型升级。支持建设农产品分拣、预冷、初加工等设施近4000个，农产品商品化处理和错峰销售能力明显增强，帮助更多好产品卖出好价钱。</p><p>流通业态方式加速创新。“十四五”时期，农村网络零售额突破3万亿元，累计增长1万亿元，农村网商数超过2000万家。</p><p>袁晓明表示，商务部将接续推进农村现代流通体系建设，促进商业网络、流通方式、服务业态、市场环境升级。</p><p>优化县域“个转企”证照联办等审批流程</p><p>商务部流通发展司司长李佳路介绍，商务部将顺应县域消费需求变化，多措并举繁荣消费市场。</p><p>销售和生产两端发力，丰富优质商品供给。会同相关部门大力推动新能源汽车、绿色智能产品等下乡，鼓励企业开发符合县域消费特色的优质产品。</p><p>抓重点和补短板并举，提升服务消费能级。以城市一刻钟便民生活圈建设经验为参照，在县城因地制宜打造便民生活圈。</p><p>引进来和育本土协同，壮大优质商业主体。引进来，就是引导更多品牌连锁企业向县域下沉。育本土，就是支持发展承载地方文化的小店、老字号、作坊式品牌，帮助他们提升品牌打造、持续经营能力，培育一批文创手作、家居生活、食品茶饮等领域的经营主体。</p><p>促创新和抓规范并重，推动业态模式创新。鼓励有条件的地方发展虚拟现实、沉浸式体验，“人工智能+消费”等。</p><p>个体工商户是下沉市场中数量最多的经营主体。市场监管总局登记注册局负责人杜林亚介绍，截至2026年7月底，下沉市场在册个体工商户数量对比企业数量为209∶100，显著高于一二线城市中的85∶100，数量超过7800万，其中86%从事的都是服务业相关行业。</p><p>《意见》提出，“在符合条件的同一县域地区推行连锁企业和商贸个体工商户‘一照多址’”“进一步优化县域‘个转企’证照联办等审批流程”。</p><p>杜林亚说，个体工商户“一照多址”和“个转企”证照联办，是市场监管部门推出的两项制度创新。“一照多址”就是指个体工商户可以在其登记机关辖区内申请登记多个实体经营场所，并且将所有实体经营场所都记载于营业执照上。“个转企”证照联办是指个体工商户可以通过变更登记的方式直接转型为企业，依法保留字号、成立时间、统一社会信用代码等经营要素，并可以同步办理税务、公章刻制、社保登记、住房公积金缴存登记等事项。</p><p>有力促进农产品消费，推动县域文旅提质升级</p><p>农产品消费一头连着百姓餐桌，另一头连着农业生产，在活跃县域消费中发挥了重要作用。农业农村部市场与信息化司负责人宋丹阳介绍，近年来，农业农村部会同有关部门强化工作指导，优化供给端、创新流通端、激活市场端，有力促进农产品消费。</p><p>卖出好价钱，重点是抓好品牌培育。深入实施农业品牌精品培育计划，指导各地建立农业品牌目录，打造一批影响力大、带动力强的区域公用品牌，带动企业品牌和产品品牌协同发展。</p><p>找到好销路，重点是抓好产销对接。持续开展“互联网+”农产品出村进城工程，推动大型电商平台、批发市场、连锁超市与主产区建立稳定的对接关系。</p><p>融进新业态，重点是抓好消费场景打造。结合休闲农业、农事体验等新业态，打造丰收市集、非遗工坊等农产品消费新场景，鼓励各地举办形式多样的农产品促消费活动，引导城乡居民就近消费、融合消费，让县域消费不仅有“烟火气”，更有“新活力”。</p><p>宋丹阳说，农业农村部将加快构建农产品营销服务体系，实施农产品农业品牌提升行动，常态化开展消费促进活动，释放多样化、品质化、差异化消费潜力。</p><p>文化和旅游部产业发展司负责人辜科伟说，“奔县游”、乡村游成为下沉市场消费新热点。文化和旅游部将聚焦产品业态供给、场景、活动等3个方面推动县域文旅提质升级，促进文旅消费迸发更大活力。</p><p>提升供给品质，让县域文旅有看头。指导113个县开展文化产业赋能乡村振兴试点，实施乡村旅游提质增效行动。</p><p>拓展消费场景，让下沉市场有热度。研究制定相关行业标准，引导夜间文旅经济健康有序发展，支持有条件的地方打造特色鲜明的夜间文旅消费场景。</p><p>丰富活动载体，让文旅服务有温度。将举办国庆文旅消费月，围绕迎国庆、赏秋景推出一系列文旅活动、惠民措施和便民服务，加大对县域乡村文旅目的地的推介力度。</p><p><a href="https://scs.moa.gov.cn/gzdt/202608/t20260828_6487083.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',33)])])}const m=e(s,[["render",r]]);export{f as __pageData,m as default};
